-- Migración 2 (parte) · geo_semilla_municipios_3 — municipios de los departamentos 25–50
-- (filas de supabase/seed/geo.sql sin cambios; separado de `geo` por tamaño). Cada parte contiene
-- departamentos completos, así la FK diferida codigo_geometria se resuelve dentro de la parte.

on conflict (codigo) do update set
  departamento_codigo = excluded.departamento_codigo,
  nombre = excluded.nombre,
  nombre_normalizado = excluded.nombre_normalizado,
  tipo = excluded.tipo,
  es_capital = excluded.es_capital,
  lon = excluded.lon,
  lat = excluded.lat,
  codigo_geometria = excluded.codigo_geometria,
  bbox = excluded.bbox;

do $$ begin
  assert (select count(*) from public.municipios where departamento_codigo between '25' and '50') = 258,
         'municipios 25–50: conteo inesperado';
end $$;
